<?php
namespace App\Notifications;
use App\Models\Election; use App\Traits\HasOrganizationTheme; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class ElectionResultsPublishedNotification extends Notification implements ShouldQueue
 { use Queueable, HasOrganizationTheme; protected $election;
 public function __construct(Election $election){$this->election=$election;if(config('queue.default') !== 'sync'){$this->onConnection('redis');$this->onQueue('emails');}} public function via(object $notifiable):array{return ['mail','database'];}
 public function toMail(object $notifiable):MailMessage{$t=$this->getOrganizationTheme($notifiable,$this->election->organization);$votes=$this->election->candidates()->sum('vote_count');return (new MailMessage)->subject('Election results are available: '.$this->election->title)->view(['html'=>'emails.election','text'=>'emails.election-text'],['organizationName'=>$t['organization_name'],'organizationLogo'=>$t['logo_url'],'primaryColor'=>$t['primary_color'],'recipientName'=>$notifiable->first_name,'title'=>'Election results are available','preheader'=>'The official results have been published.','intro'=>'The election has concluded and the official results are now available. Thank you for taking part in the student voting process.','highlight'=>$this->election->title,'details'=>['Total votes counted'=>number_format($votes),'Election period'=>$this->election->start_date->format('F j, Y').' - '.$this->election->end_date->format('F j, Y')],'body'=>'View the final rankings and winners through the button below.','actionLabel'=>'View election results','actionUrl'=>url('/elections')]);}
 public function toArray(object $notifiable):array{return ['type'=>'election_results_published','election_id'=>$this->election->id,'organization_id'=>$this->election->organization_id,'title'=>'Election Results Published','message'=>$this->election->title,'icon'=>'ph-trophy','color'=>'blue','url'=>url('/elections')];}
}
